-- Sprint 3 (data-model.md 2-2, 2-5..2-7): task templates, tasks, extensions, submissions,
-- reviews, attachments (C4), notes, timeline events and reminders. Generated by drizzle-kit
-- and reviewed; the last statement is hand-written (see below).
CREATE TABLE "task_templates" (
	"id" uuid PRIMARY KEY NOT NULL,
	"stage_id" uuid,
	"title" text NOT NULL,
	"description" text,
	"kind" text DEFAULT 'path_assignment' NOT NULL,
	"submission_type" text DEFAULT 'text' NOT NULL,
	"default_due_days" integer,
	"required_for_gate" boolean DEFAULT false NOT NULL,
	"suggest_on_stage_entry" boolean DEFAULT false NOT NULL,
	"sort_order" integer DEFAULT 0 NOT NULL,
	"is_active" boolean DEFAULT true NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "task_templates_kind_check" CHECK ("task_templates"."kind" IN ('path_assignment', 'custom', 'follow_up', 'session_prep')),
	CONSTRAINT "task_templates_submission_type_check" CHECK ("task_templates"."submission_type" IN ('text', 'link', 'file', 'checkbox', 'proposal_review', 'profile_review')),
	CONSTRAINT "task_templates_due_days_check" CHECK ("task_templates"."default_due_days" IS NULL OR "task_templates"."default_due_days" BETWEEN 1 AND 365)
);
--> statement-breakpoint
CREATE TABLE "attachments" (
	"id" uuid PRIMARY KEY NOT NULL,
	"storage_key" text NOT NULL,
	"original_name" text NOT NULL,
	"mime_type" text NOT NULL,
	"size_bytes" integer NOT NULL,
	"width" integer NOT NULL,
	"height" integer NOT NULL,
	"uploaded_by" uuid NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"submission_id" uuid,
	"question_message_id" uuid,
	"milestone_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "attachments_status_check" CHECK ("attachments"."status" IN ('pending', 'linked')),
	CONSTRAINT "attachments_mime_check" CHECK ("attachments"."mime_type" IN ('image/jpeg', 'image/png', 'image/webp')),
	CONSTRAINT "attachments_parent_check" CHECK (num_nonnulls("attachments"."submission_id", "attachments"."question_message_id", "attachments"."milestone_id") = CASE WHEN "attachments"."status" = 'pending' THEN 0 ELSE 1 END)
);
--> statement-breakpoint
CREATE TABLE "reminders" (
	"id" uuid PRIMARY KEY NOT NULL,
	"owner_id" uuid NOT NULL,
	"student_id" uuid,
	"text" text NOT NULL,
	"due_at" timestamp with time zone NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"done_at" timestamp with time zone,
	"snooze_count" integer DEFAULT 0 NOT NULL,
	"source" text DEFAULT 'manual' NOT NULL,
	"system_key" text,
	"created_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "reminders_status_check" CHECK ("reminders"."status" IN ('open', 'done', 'cancelled')),
	CONSTRAINT "reminders_source_check" CHECK ("reminders"."source" IN ('manual', 'system')),
	CONSTRAINT "reminders_done_check" CHECK (("reminders"."status" = 'done') = ("reminders"."done_at" IS NOT NULL)),
	CONSTRAINT "reminders_system_key_check" CHECK (("reminders"."source" = 'system') = ("reminders"."system_key" IS NOT NULL)),
	CONSTRAINT "reminders_snooze_check" CHECK ("reminders"."snooze_count" >= 0),
	CONSTRAINT "reminders_text_check" CHECK (btrim("reminders"."text") <> '')
);
--> statement-breakpoint
CREATE TABLE "reviews" (
	"id" uuid PRIMARY KEY NOT NULL,
	"submission_id" uuid NOT NULL,
	"reviewer_id" uuid NOT NULL,
	"outcome" text NOT NULL,
	"feedback_text" text NOT NULL,
	"score" smallint,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "reviews_outcome_check" CHECK ("reviews"."outcome" IN ('accepted', 'changes_requested')),
	CONSTRAINT "reviews_score_check" CHECK ("reviews"."score" IS NULL OR "reviews"."score" BETWEEN 1 AND 5)
);
--> statement-breakpoint
CREATE TABLE "submissions" (
	"id" uuid PRIMARY KEY NOT NULL,
	"task_id" uuid NOT NULL,
	"version" integer NOT NULL,
	"body_text" text,
	"links" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"platform_id" uuid,
	"job_post_text" text,
	"proposal_text" text,
	"profile_text" text,
	"ai_use_consent" boolean DEFAULT false NOT NULL,
	"ai_use_consent_at" timestamp with time zone,
	"submitted_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "submissions_version_check" CHECK ("submissions"."version" >= 1),
	CONSTRAINT "submissions_consent_check" CHECK (NOT "submissions"."ai_use_consent" OR "submissions"."ai_use_consent_at" IS NOT NULL)
);
--> statement-breakpoint
CREATE TABLE "task_extensions" (
	"id" uuid PRIMARY KEY NOT NULL,
	"task_id" uuid NOT NULL,
	"previous_due_at" timestamp with time zone NOT NULL,
	"new_due_at" timestamp with time zone NOT NULL,
	"reason" text NOT NULL,
	"actor_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "task_extensions_reason_check" CHECK (btrim("task_extensions"."reason") <> '')
);
--> statement-breakpoint
CREATE TABLE "tasks" (
	"id" uuid PRIMARY KEY NOT NULL,
	"student_id" uuid NOT NULL,
	"title" text NOT NULL,
	"description" text,
	"kind" text NOT NULL,
	"submission_type" text NOT NULL,
	"stage_id" uuid,
	"required_for_gate" boolean DEFAULT false NOT NULL,
	"priority" text DEFAULT 'normal' NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"due_at" timestamp with time zone NOT NULL,
	"original_due_at" timestamp with time zone NOT NULL,
	"reviewer_id" uuid NOT NULL,
	"created_by" uuid NOT NULL,
	"template_id" uuid,
	"batch_id" uuid,
	"profile_id" uuid,
	"revision_count" integer DEFAULT 0 NOT NULL,
	"extension_count" integer DEFAULT 0 NOT NULL,
	"status_changed_at" timestamp with time zone NOT NULL,
	"last_submitted_at" timestamp with time zone,
	"closed_at" timestamp with time zone,
	"cancel_reason" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tasks_status_check" CHECK ("tasks"."status" IN ('open', 'in_progress', 'submitted', 'changes_requested', 'accepted', 'cancelled')),
	CONSTRAINT "tasks_kind_check" CHECK ("tasks"."kind" IN ('path_assignment', 'custom', 'follow_up', 'session_prep')),
	CONSTRAINT "tasks_submission_type_check" CHECK ("tasks"."submission_type" IN ('text', 'link', 'file', 'checkbox', 'proposal_review', 'profile_review')),
	CONSTRAINT "tasks_priority_check" CHECK ("tasks"."priority" IN ('normal', 'urgent')),
	CONSTRAINT "tasks_counts_check" CHECK ("tasks"."revision_count" >= 0 AND "tasks"."extension_count" >= 0),
	CONSTRAINT "tasks_cancel_reason_check" CHECK ("tasks"."status" <> 'cancelled' OR ("tasks"."cancel_reason" IS NOT NULL AND btrim("tasks"."cancel_reason") <> '')),
	CONSTRAINT "tasks_closed_at_check" CHECK (("tasks"."status" IN ('accepted', 'cancelled')) = ("tasks"."closed_at" IS NOT NULL))
);
--> statement-breakpoint
CREATE TABLE "notes" (
	"id" uuid PRIMARY KEY NOT NULL,
	"student_id" uuid NOT NULL,
	"author_id" uuid NOT NULL,
