	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"deleted_at" timestamp with time zone,
	CONSTRAINT "notes_kind_check" CHECK ("notes"."kind" IN ('note', 'session', 'call', 'external_message', 'weekly_review')),
	CONSTRAINT "notes_visibility_check" CHECK ("notes"."visibility" IN ('internal', 'shared')),
	CONSTRAINT "notes_body_check" CHECK (btrim("notes"."body") <> '')
);
